    typealias SwiftType = RustComponentsError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> RustComponentsError {
        let variant: Int32 = try readInt(&buf)
        switch variant {




        case 1: return .Core(
            try FfiConverterString.read(from: &buf)
            )
        case 2: return .Sync(
            try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: RustComponentsError, into buf: inout [UInt8]) {
        switch value {





